// axil_timer: 32-bit down-counting timer, one-shot and periodic modes,
// level interrupt, AXI4-Lite subordinate port.
// Implements microarchitecture.md against interface_spec.md.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL    = 2'd0;
    localparam [1:0] IDX_LOAD    = 2'd1;
    localparam [1:0] IDX_COUNT   = 2'd2;
    localparam [1:0] IDX_STATUS  = 2'd3;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held_q;
    reg                  aw_held_d;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg [ADDR_WIDTH-1:0] aw_addr_d;
    reg                  w_held_q;
    reg                  w_held_d;
    reg [31:0]           w_data_q;
    reg [31:0]           w_data_d;
    reg [3:0]            w_strb_q;
    reg [3:0]            w_strb_d;
    reg                  bvalid_q;
    reg                  bvalid_d;
    reg [1:0]            bresp_q;
    reg [1:0]            bresp_d;
    reg                  rvalid_q;
    reg                  rvalid_d;
    reg [31:0]           rdata_q;
    reg [31:0]           rdata_d;
    reg [1:0]            rresp_q;
    reg [1:0]            rresp_d;

    reg                  en_q;
    reg                  en_d;
    reg                  ie_q;
    reg                  ie_d;
    reg                  mode_q;
    reg                  mode_d;
    reg                  expired_q;
    reg                  expired_d;
    reg [31:0]           load_q;
    reg [31:0]           load_d;
    reg [31:0]           count_q;
    reg [31:0]           count_d;

    // ------------------------------------------------------------------
    // Channel handshakes (READYs come from flops only)
    // ------------------------------------------------------------------
    wire aw_ready = !aw_held_q && !bvalid_q;
    wire w_ready  = !w_held_q && !bvalid_q;
    wire ar_ready = !rvalid_q;

    wire aw_hs = s_axil_awvalid && aw_ready;
    wire w_hs  = s_axil_wvalid && w_ready;
    wire ar_hs = s_axil_arvalid && ar_ready;

    // Both halves of a write present, held or arriving.
    wire do_write = (aw_held_q || aw_hs) && (w_held_q || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held_q ? w_data_q : s_axil_wdata;
    wire [3:0]            wr_strb = w_held_q ? w_strb_q : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode: mapped only when word aligned and below 0x10
    // ------------------------------------------------------------------
    wire wr_hi_zero;
    wire rd_hi_zero;

    generate
        if (ADDR_WIDTH > 4) begin : g_wide_addr
            assign wr_hi_zero = (wr_addr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
            assign rd_hi_zero = (s_axil_araddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
        end else begin : g_narrow_addr
            assign wr_hi_zero = 1'b1;
            assign rd_hi_zero = 1'b1;
        end
    endgenerate

    wire       wr_mapped = (wr_addr[1:0] == 2'b00) && wr_hi_zero;
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       wr_ok     = wr_mapped && (wr_idx != IDX_COUNT);
    wire       wr_go     = do_write && wr_ok;
    wire       wr_ctrl   = wr_go && (wr_idx == IDX_CTRL) && wr_strb[0];
    wire       wr_load   = wr_go && (wr_idx == IDX_LOAD);
    wire       wr_clear  = wr_go && (wr_idx == IDX_STATUS) && wr_strb[0] && wr_data[0];

    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) && rd_hi_zero;
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    // Last cycle of a count: a COUNT of 0 is treated like 1.
    wire count_end = en_q && (count_q <= 32'd1);

    // ------------------------------------------------------------------
    // Read mux (register value before the accepting edge)
    // ------------------------------------------------------------------
    reg [31:0] rd_value;

    always @* begin
        rd_value = 32'd0;
        case (rd_idx)
            IDX_CTRL:   rd_value = {29'd0, mode_q, ie_q, en_q};
            IDX_LOAD:   rd_value = load_q;
            IDX_COUNT:  rd_value = count_q;
            IDX_STATUS: rd_value = {31'd0, expired_q};
            default:    rd_value = 32'd0;
        endcase
        if (!rd_mapped) begin
            rd_value = 32'd0;
        end
    end

    // ------------------------------------------------------------------
    // Next state
    // ------------------------------------------------------------------
    always @* begin
        aw_held_d = aw_held_q;
        aw_addr_d = aw_addr_q;
        w_held_d  = w_held_q;
        w_data_d  = w_data_q;
        w_strb_d  = w_strb_q;
        bvalid_d  = bvalid_q;
        bresp_d   = bresp_q;
        rvalid_d  = rvalid_q;
        rdata_d   = rdata_q;
        rresp_d   = rresp_q;
        en_d      = en_q;
        ie_d      = ie_q;
        mode_d    = mode_q;
        expired_d = expired_q;
        load_d    = load_q;
        count_d   = count_q;

        // Write channels: hold a half that arrives alone.
        if (aw_hs) begin
            aw_addr_d = s_axil_awaddr;
        end
        if (w_hs) begin
            w_data_d = s_axil_wdata;
            w_strb_d = s_axil_wstrb;
        end
        if (do_write) begin
            aw_held_d = 1'b0;
            w_held_d  = 1'b0;
        end else begin
            if (aw_hs) begin
                aw_held_d = 1'b1;
            end
            if (w_hs) begin
                w_held_d = 1'b1;
            end
        end

        // Write response.
        if (bvalid_q && s_axil_bready) begin
            bvalid_d = 1'b0;
        end
        if (do_write) begin
            bvalid_d = 1'b1;
            bresp_d  = wr_ok ? RESP_OKAY : RESP_SLVERR;
        end

        // Read channel.
        if (rvalid_q && s_axil_rready) begin
            rvalid_d = 1'b0;
        end
        if (ar_hs) begin
            rvalid_d = 1'b1;
            rdata_d  = rd_value;
            rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
        end

        // 1. Count step.
        if (en_q) begin
            if (count_end) begin
                if (mode_q) begin
                    count_d = load_q;
                end else begin
                    count_d = 32'd0;
                    en_d    = 1'b0;
                end
            end else begin
                count_d = count_q - 32'd1;
            end
        end

        // 2. EXPIRED: clear first, then set, so a count end beats a clear.
        if (wr_clear) begin
            expired_d = 1'b0;
        end
        if (count_end) begin
            expired_d = 1'b1;
        end

        // 3. CTRL write (only with wstrb[0]); wins over the count step.
        if (wr_ctrl) begin
            ie_d   = wr_data[1];
            mode_d = wr_data[2];
            if (wr_data[0]) begin
                en_d    = 1'b1;
                count_d = load_q;
            end else begin
                en_d = 1'b0;
            end
        end

        // 4. LOAD write, byte by byte.
        if (wr_load) begin
            if (wr_strb[0]) begin
                load_d[7:0] = wr_data[7:0];
            end
            if (wr_strb[1]) begin
                load_d[15:8] = wr_data[15:8];
            end
            if (wr_strb[2]) begin
                load_d[23:16] = wr_data[23:16];
            end
            if (wr_strb[3]) begin
                load_d[31:24] = wr_data[31:24];
            end
        end
    end

    // ------------------------------------------------------------------
    // Registers, synchronous active-low reset
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held_q <= 1'b0;
            aw_addr_q <= {ADDR_WIDTH{1'b0}};
            w_held_q  <= 1'b0;
            w_data_q  <= 32'd0;
            w_strb_q  <= 4'd0;
            bvalid_q  <= 1'b0;
            bresp_q   <= RESP_OKAY;
            rvalid_q  <= 1'b0;
            rdata_q   <= 32'd0;
            rresp_q   <= RESP_OKAY;
            en_q      <= 1'b0;
            ie_q      <= 1'b0;
            mode_q    <= 1'b0;
            expired_q <= 1'b0;
            load_q    <= 32'd0;
            count_q   <= 32'd0;
        end else begin
            aw_held_q <= aw_held_d;
            aw_addr_q <= aw_addr_d;
            w_held_q  <= w_held_d;
            w_data_q  <= w_data_d;
            w_strb_q  <= w_strb_d;
            bvalid_q  <= bvalid_d;
            bresp_q   <= bresp_d;
            rvalid_q  <= rvalid_d;
            rdata_q   <= rdata_d;
            rresp_q   <= rresp_d;
            en_q      <= en_d;
            ie_q      <= ie_d;
            mode_q    <= mode_d;
            expired_q <= expired_d;
            load_q    <= load_d;
            count_q   <= count_d;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign s_axil_awready = aw_ready;
    assign s_axil_wready  = w_ready;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_arready = ar_ready;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rdata   = rdata_q;
    assign s_axil_rresp   = rresp_q;
    assign irq            = expired_q && ie_q;

`ifdef FORMAL
    // Design-intent properties (not a submitted proof).
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) begin
            assume (!aresetn);
        end
    end

    always @(*) begin
        if (f_past_valid) begin
            assert (!(aw_held_q && w_held_q));
            assert (!(aw_held_q && bvalid_q));
            assert (!(w_held_q && bvalid_q));
            assert ((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
            assert ((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(f_past_valid)) begin
            if (!$past(aresetn)) begin
                assert (!bvalid_q && !rvalid_q && !en_q && !expired_q);
            end else begin
                if ($past(bvalid_q) && !$past(s_axil_bready)) begin
                    assert (bvalid_q && (bresp_q == $past(bresp_q)));
                end
                if ($past(rvalid_q) && !$past(s_axil_rready)) begin
                    assert (rvalid_q && (rdata_q == $past(rdata_q))
                            && (rresp_q == $past(rresp_q)));
                end
            end
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
