`define CHECK(cond, msg) begin if (cond) passed = passed + 1; else begin failed = failed + 1; $error msg; end end

module axil_timer_tb;

    localparam [1:0] OKAY   = 2'b00;
    localparam [1:0] SLVERR = 2'b10;

    reg clk;
    reg aresetn;
    reg sel8;

    reg [7:0]  tb_awaddr;
    reg        tb_awvalid;
    reg [31:0] tb_wdata;
    reg [3:0]  tb_wstrb;
    reg        tb_wvalid;
    reg        tb_bready;
    reg [7:0]  tb_araddr;
    reg        tb_arvalid;
    reg        tb_rready;

    wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
    wire [1:0]  bresp4, rresp4;
    wire [31:0] rdata4;
    wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
    wire [1:0]  bresp8, rresp8;
    wire [31:0] rdata8;

    wire        awready = sel8 ? awready8 : awready4;
    wire        wready  = sel8 ? wready8  : wready4;
    wire        bvalid  = sel8 ? bvalid8  : bvalid4;
    wire [1:0]  bresp   = sel8 ? bresp8   : bresp4;
    wire        arready = sel8 ? arready8 : arready4;
    wire        rvalid  = sel8 ? rvalid8  : rvalid4;
    wire [31:0] rdata   = sel8 ? rdata8   : rdata4;
    wire [1:0]  rresp   = sel8 ? rresp8   : rresp4;
    wire        mon_irq = sel8 ? irq8     : irq4;

    axil_timer #(.ADDR_WIDTH(4)) dut4 (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (tb_awaddr[3:0]),
        .s_axil_awvalid (tb_awvalid & ~sel8),
        .s_axil_awready (awready4),
        .s_axil_wdata   (tb_wdata),
        .s_axil_wstrb   (tb_wstrb),
        .s_axil_wvalid  (tb_wvalid & ~sel8),
        .s_axil_wready  (wready4),
        .s_axil_bresp   (bresp4),
        .s_axil_bvalid  (bvalid4),
        .s_axil_bready  (tb_bready & ~sel8),
        .s_axil_araddr  (tb_araddr[3:0]),
        .s_axil_arvalid (tb_arvalid & ~sel8),
        .s_axil_arready (arready4),
        .s_axil_rdata   (rdata4),
        .s_axil_rresp   (rresp4),
        .s_axil_rvalid  (rvalid4),
        .s_axil_rready  (tb_rready & ~sel8),
        .irq            (irq4)
    );

    axil_timer #(.ADDR_WIDTH(8)) dut8 (
        .aclk           (clk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (tb_awaddr),
        .s_axil_awvalid (tb_awvalid & sel8),
        .s_axil_awready (awready8),
        .s_axil_wdata   (tb_wdata),
        .s_axil_wstrb   (tb_wstrb),
        .s_axil_wvalid  (tb_wvalid & sel8),
        .s_axil_wready  (wready8),
        .s_axil_bresp   (bresp8),
        .s_axil_bvalid  (bvalid8),
        .s_axil_bready  (tb_bready & sel8),
        .s_axil_araddr  (tb_araddr),
        .s_axil_arvalid (tb_arvalid & sel8),
        .s_axil_arready (arready8),
        .s_axil_rdata   (rdata8),
        .s_axil_rresp   (rresp8),
        .s_axil_rvalid  (rvalid8),
        .s_axil_rready  (tb_rready & sel8),
        .irq            (irq8)
    );

    integer passed;
    integer failed;
    integer edge_cnt = 0;
    integer rise_cnt;
    integer last_rise;
    reg     irq_prev;
    integer last_eff;
    reg [511:0] nonce;
    reg [31:0]  mload;

    integer E;
    integer S;
    integer acc;
    integer expv;
    integer rc;
    integer rc2;
    integer e_tmp;
    reg [1:0]  r;
    reg [31:0] rdat;
    reg [31:0] rdat2;

    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    // Rising edges so far; read at negedges.
    always @(posedge clk) edge_cnt <= edge_cnt + 1;

    // irq rise monitor, sampled at negedges (outputs are stable then).
    always @(negedge clk) begin
        if (!aresetn) begin
            rise_cnt  = 0;
            last_rise = -1;
            irq_prev  = 1'b0;
        end else begin
            if (mon_irq && !irq_prev) begin
                rise_cnt  = rise_cnt + 1;
                last_rise = edge_cnt;
            end
            irq_prev = mon_irq;
        end
    end

    function [31:0] merge;
        input [31:0] old_v;
        input [31:0] new_v;
        input [3:0]  s;
        begin
            merge = old_v;
            if (s[0]) merge[7:0]   = new_v[7:0];
            if (s[1]) merge[15:8]  = new_v[15:8];
            if (s[2]) merge[23:16] = new_v[23:16];
            if (s[3]) merge[31:24] = new_v[31:24];
        end
    endfunction

    task tick;
        begin
            @(posedge clk);
            @(negedge clk);
        end
    endtask

    task wait_cycles;
        input integer n;
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) begin
                @(negedge clk);
            end
        end
    endtask

    // All bus tasks start and end at a negedge.
    task axi_write;
        input  [7:0]   addr;
        input  [31:0]  data;
        input  [3:0]   strb;
        input  integer order;
        input  integer gap;
        input  integer bdelay;
        output [1:0]   resp;
        output integer eff;
        integer guard;
        integer k;
        reg aw_done;
        reg w_done;
        reg aw_fire;
        reg w_fire;
        reg [1:0] resp0;
        begin
            aw_done = 1'b0;
            w_done  = 1'b0;
            guard   = 0;
            eff     = -1;
            tb_awaddr = addr;
            tb_wdata  = data;
            tb_wstrb  = strb;
            if (order != 2) tb_awvalid = 1'b1;
            if (order != 1) tb_wvalid  = 1'b1;
            while (!(aw_done && w_done) && (guard < 100)) begin
                aw_fire = tb_awvalid & awready;
                w_fire  = tb_wvalid & wready;
                @(posedge clk);
                @(negedge clk);
                guard = guard + 1;
                if (aw_fire) begin
                    aw_done = 1'b1;
                    tb_awvalid = 1'b0;
                end
                if (w_fire) begin
                    w_done = 1'b1;
                    tb_wvalid = 1'b0;
                end
                if (aw_done && w_done) begin
                    eff = edge_cnt;
                end else begin
                    if (aw_fire && !w_done) begin
                        `CHECK(awready == 1'b0, ("AWREADY high while a write address is held"))
                        `CHECK(bvalid == 1'b0, ("BVALID high before the write data arrived"))
                        if (order == 1) begin
                            for (k = 0; k < gap; k = k + 1) begin
                                tick;
                                `CHECK(awready == 1'b0, ("AWREADY high while a write address is held (gap)"))
                                `CHECK(bvalid == 1'b0, ("BVALID high before the write data arrived (gap)"))
                            end
                            tb_wvalid = 1'b1;
                        end
                    end
                    if (w_fire && !aw_done) begin
                        `CHECK(wready == 1'b0, ("WREADY high while write data is held"))
                        `CHECK(bvalid == 1'b0, ("BVALID high before the write address arrived"))
                        if (order == 2) begin
                            for (k = 0; k < gap; k = k + 1) begin
                                tick;
                                `CHECK(wready == 1'b0, ("WREADY high while write data is held (gap)"))
                                `CHECK(bvalid == 1'b0, ("BVALID high before the write address arrived (gap)"))
                            end
                            tb_awvalid = 1'b1;
                        end
                    end
                end
            end
            `CHECK(eff >= 0, ("write to 0x%h: handshake timed out", addr))
            `CHECK(bvalid == 1'b1, ("write to 0x%h: BVALID not high after the completing edge", addr))
            `CHECK(awready == 1'b0 && wready == 1'b0, ("write to 0x%h: READY high while BVALID waits", addr))
            resp0 = bresp;
            for (k = 0; k < bdelay; k = k + 1) begin
                tick;
                `CHECK(bvalid == 1'b1 && bresp == resp0, ("write to 0x%h: BVALID/BRESP not held under back-pressure", addr))
            end
            tb_bready = 1'b1;
            tick;
            tb_bready = 1'b0;
            `CHECK(bvalid == 1'b0, ("write to 0x%h: BVALID did not drop after BREADY", addr))
            resp = resp0;
        end
    endtask

    task axi_read;
        input  [7:0]   addr;
        input  integer rdelay;
        output [31:0]  data;
        output [1:0]   resp;
        output integer acc_e;
        integer guard;
        integer k;
        reg done;
        reg fire;
        reg [31:0] d0;
        reg [1:0]  r0;
        begin
            done  = 1'b0;
            guard = 0;
            acc_e = -1;
            tb_araddr  = addr;
            tb_arvalid = 1'b1;
            while (!done && (guard < 100)) begin
                fire = tb_arvalid & arready;
                @(posedge clk);
                @(negedge clk);
                guard = guard + 1;
                if (fire) begin
                    done = 1'b1;
                    tb_arvalid = 1'b0;
                    acc_e = edge_cnt;
                end
            end
            `CHECK(acc_e >= 0, ("read of 0x%h: handshake timed out", addr))
            `CHECK(rvalid == 1'b1, ("read of 0x%h: RVALID not high after the accepting edge", addr))
            `CHECK(arready == 1'b0, ("read of 0x%h: ARREADY high while RVALID waits", addr))
            d0 = rdata;
            r0 = rresp;
            for (k = 0; k < rdelay; k = k + 1) begin
                tick;
                `CHECK(rvalid == 1'b1 && rdata == d0 && rresp == r0, ("read of 0x%h: R channel not held under back-pressure", addr))
            end
            tb_rready = 1'b1;
            tick;
            tb_rready = 1'b0;
            `CHECK(rvalid == 1'b0, ("read of 0x%h: RVALID did not drop after RREADY", addr))
            data = d0;
            resp = r0;
        end
    endtask

    task wr;
        input [7:0]  addr;
        input [31:0] data;
        input [3:0]  strb;
        input [1:0]  exp_r;
        reg [1:0] wr_r;
        integer   wr_e;
        begin
            axi_write(addr, data, strb, 0, 0, 0, wr_r, wr_e);
            `CHECK(wr_r == exp_r, ("write 0x%h to 0x%h: resp %b, expected %b", data, addr, wr_r, exp_r))
            last_eff = wr_e;
        end
    endtask

    task rdchk;
        input [7:0]  addr;
        input [31:0] exp_d;
        input [1:0]  exp_r;
        reg [31:0] rd_d;
        reg [1:0]  rd_r;
        integer    rd_a;
        begin
            axi_read(addr, 0, rd_d, rd_r, rd_a);
            `CHECK(rd_d == exp_d, ("read 0x%h: data 0x%h, expected 0x%h", addr, rd_d, exp_d))
            `CHECK(rd_r == exp_r, ("read 0x%h: resp %b, expected %b", addr, rd_r, exp_r))
        end
    endtask

    // Make a write take effect on edge t (must be called before edge t-1 ends).
    task write_at;
        input integer t;
        input [7:0]  addr;
        input [31:0] data;
        input [3:0]  strb;
        begin
            `CHECK(edge_cnt <= t - 1, ("write_at: target edge %0d already passed (now %0d)", t, edge_cnt))
            while (edge_cnt < t - 1) @(negedge clk);
            wr(addr, data, strb, OKAY);
            `CHECK(last_eff == t, ("write landed on edge %0d, intended %0d", last_eff, t))
        end
    endtask

    task wait_irq;
        input integer limit;
        integer g;
        begin
            g = 0;
            while (!mon_irq && (g < limit)) begin
                @(negedge clk);
                g = g + 1;
            end
            `CHECK(mon_irq == 1'b1, ("irq did not rise within %0d cycles", limit))
            @(negedge clk);
        end
    endtask

    task oneshot_timed;
        input [31:0]  n;
        input integer len;
        integer e0;
        integer rc0;
        begin
            wr(8'h04, n, 4'hF, OKAY);
            rc0 = rise_cnt;
            wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
            e0 = last_eff;
            wait_irq(len + 50);
            `CHECK(last_rise == e0 + len, ("one-shot LOAD %0d: irq rose on edge %0d, expected %0d", n, last_rise, e0 + len))
            `CHECK(rise_cnt == rc0 + 1, ("one-shot LOAD %0d: %0d irq rises, expected 1", n, rise_cnt - rc0))
            rdchk(8'h00, 32'h0000_0002, OKAY);
            rdchk(8'h08, 32'h0000_0000, OKAY);
            wr(8'h0C, 32'h0000_0001, 4'h1, OKAY);
            `CHECK(mon_irq == 1'b0, ("one-shot LOAD %0d: irq still high after clear", n))
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        nonce  = 512'd0;
        sel8   = 1'b0;
        aresetn = 1'b0;
        tb_awaddr  = 8'h00;
        tb_awvalid = 1'b0;
        tb_wdata   = 32'h0;
        tb_wstrb   = 4'h0;
        tb_wvalid  = 1'b0;
        tb_bready  = 1'b0;
        tb_araddr  = 8'h00;
        tb_arvalid = 1'b0;
        tb_rready  = 1'b0;
        last_eff   = -1;
        mload      = 32'h0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 512'd0;

        repeat (4) @(negedge clk);
        aresetn = 1'b1;

        // ---------------- T1: reset values ----------------
        `CHECK(bvalid4 == 1'b0 && rvalid4 == 1'b0 && irq4 == 1'b0, ("aw4: BVALID/RVALID/irq not low after reset"))
        `CHECK(bvalid8 == 1'b0 && rvalid8 == 1'b0 && irq8 == 1'b0, ("aw8: BVALID/RVALID/irq not low after reset"))
        `CHECK(awready4 == 1'b1 && wready4 == 1'b1 && arready4 == 1'b1, ("aw4: READYs not high when idle"))
        rdchk(8'h00, 32'h0, OKAY);
        rdchk(8'h04, 32'h0, OKAY);
        rdchk(8'h08, 32'h0, OKAY);
        rdchk(8'h0C, 32'h0, OKAY);

        // ---------------- T2: LOAD with partial strobes ----------------
        wr(8'h04, 32'hFFFF_FFFF, 4'hF, OKAY);
        mload = merge(mload, 32'hFFFF_FFFF, 4'hF);
        wr(8'h04, 32'h1234_5678, 4'b0101, OKAY);
        mload = merge(mload, 32'h1234_5678, 4'b0101);
        `CHECK(mload == 32'hFF34_FF78, ("model merge mismatch"))
        rdchk(8'h04, mload, OKAY);
        wr(8'h04, 32'h0000_0000, 4'b0000, OKAY);
        rdchk(8'h04, mload, OKAY);
        wr(8'h04, 32'hAABB_CCDD, 4'b1010, OKAY);
        mload = merge(mload, 32'hAABB_CCDD, 4'b1010);
        `CHECK(mload == 32'hAA34_CC78, ("model merge mismatch"))
        rdchk(8'h04, mload, OKAY);

        // ---------------- T3: channel orders and back-pressure ----------------
        axi_write(8'h04, 32'h0000_1111, 4'hF, 1, 3, 4, r, e_tmp);
        `CHECK(r == OKAY, ("AW-first write resp %b", r))
        mload = 32'h0000_1111;
        axi_read(8'h04, 5, rdat, r, acc);
        `CHECK(rdat == mload && r == OKAY, ("read after AW-first write: 0x%h %b", rdat, r))
        axi_write(8'h04, 32'h0000_2222, 4'hF, 2, 2, 0, r, e_tmp);
        `CHECK(r == OKAY, ("W-first write resp %b", r))
        mload = 32'h0000_2222;
        axi_read(8'h04, 0, rdat, r, acc);
        `CHECK(rdat == mload && r == OKAY, ("read after W-first write: 0x%h %b", rdat, r))
        axi_write(8'h04, 32'h0000_3333, 4'hF, 0, 0, 6, r, e_tmp);
        `CHECK(r == OKAY, ("together write resp %b", r))
        mload = 32'h0000_3333;
        rdchk(8'h04, mload, OKAY);
        axi_write(8'h0C, 32'h0000_0000, 4'hF, 1, 0, 2, r, e_tmp);
        `CHECK(r == OKAY, ("AW-first, no gap, STATUS write resp %b", r))
        axi_write(8'h0C, 32'h0000_0000, 4'hF, 2, 0, 0, r, e_tmp);
        `CHECK(r == OKAY, ("W-first, no gap, STATUS write resp %b", r))
        rdchk(8'h0C, 32'h0, OKAY);

        // read and write on the same clock
        tb_awaddr  = 8'h04;
        tb_wdata   = 32'h0000_4444;
        tb_wstrb   = 4'hF;
        tb_awvalid = 1'b1;
        tb_wvalid  = 1'b1;
        tb_araddr  = 8'h04;
        tb_arvalid = 1'b1;
        tick;
        tb_awvalid = 1'b0;
        tb_wvalid  = 1'b0;
        tb_arvalid = 1'b0;
        `CHECK(bvalid == 1'b1 && bresp == OKAY, ("simultaneous: write response missing"))
        `CHECK(rvalid == 1'b1 && rresp == OKAY && rdata == 32'h0000_3333, ("simultaneous: read 0x%h, expected old 0x00003333", rdata))
        tick;
        `CHECK(bvalid == 1'b1 && rvalid == 1'b1 && rdata == 32'h0000_3333, ("simultaneous: responses not held"))
        tb_bready = 1'b1;
        tb_rready = 1'b1;
        tick;
        tb_bready = 1'b0;
        tb_rready = 1'b0;
        `CHECK(bvalid == 1'b0 && rvalid == 1'b0, ("simultaneous: responses did not drop"))
        mload = 32'h0000_4444;
        rdchk(8'h04, mload, OKAY);

        // ---------------- T4: COUNT read only, SLVERR policy ----------------
        wr(8'h08, 32'h0000_1234, 4'hF, SLVERR);
        rdchk(8'h08, 32'h0, OKAY);
        wr(8'h05, 32'hDEAD_BEEF, 4'hF, SLVERR);
        wr(8'h06, 32'hDEAD_BEEF, 4'hF, SLVERR);
        wr(8'h07, 32'hDEAD_BEEF, 4'hF, SLVERR);
        rdchk(8'h04, mload, OKAY);
        wr(8'h01, 32'h0000_0007, 4'hF, SLVERR);
        wr(8'h02, 32'h0000_0007, 4'hF, SLVERR);
        rdchk(8'h00, 32'h0, OKAY);
        wr(8'h0D, 32'h0000_0001, 4'hF, SLVERR);
        rdchk(8'h01, 32'h0, SLVERR);
        rdchk(8'h05, 32'h0, SLVERR);
        rdchk(8'h06, 32'h0, SLVERR);
        rdchk(8'h0B, 32'h0, SLVERR);
        rdchk(8'h0F, 32'h0, SLVERR);
        rdchk(8'h08, 32'h0, OKAY);
        rdchk(8'h0C, 32'h0, OKAY);
        `CHECK(mon_irq == 1'b0, ("irq high after SLVERR tests"))

        // ---------------- T5: CTRL write without wstrb[0] ----------------
        wr(8'h00, 32'h0000_0007, 4'b1110, OKAY);
        wait_cycles(5);
        rdchk(8'h00, 32'h0, OKAY);
        rdchk(8'h08, 32'h0, OKAY);
        rdchk(8'h0C, 32'h0, OKAY);
        `CHECK(mon_irq == 1'b0, ("irq high after CTRL write without wstrb[0]"))

        // ---------------- T6: one-shot timed ----------------
        wr(8'h04, 32'd20, 4'hF, OKAY);
        rc = rise_cnt;
        wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
        E = last_eff;
        axi_read(8'h08, 0, rdat, r, acc);
        expv = 20 - (acc - 1 - E);
        `CHECK(rdat == expv && r == OKAY, ("COUNT while counting: 0x%h, expected %0d", rdat, expv))
        wait_irq(100);
        `CHECK(last_rise == E + 20, ("one-shot 20: irq rose on edge %0d, expected %0d", last_rise, E + 20))
        `CHECK(rise_cnt == rc + 1, ("one-shot 20: wrong number of irq rises"))
        rdchk(8'h00, 32'h0000_0002, OKAY);
        rdchk(8'h08, 32'h0, OKAY);
        rdchk(8'h0C, 32'h0000_0001, OKAY);
        wait_cycles(40);
        `CHECK(rise_cnt == rc + 1, ("one-shot 20: a second interrupt occurred"))
        `CHECK(mon_irq == 1'b1, ("one-shot 20: irq not held as a level"))
        rdchk(8'h08, 32'h0, OKAY);
        wr(8'h0C, 32'h0000_0000, 4'hF, OKAY);
        rdchk(8'h0C, 32'h0000_0001, OKAY);
        wr(8'h0C, 32'h0000_0001, 4'b1110, OKAY);
        rdchk(8'h0C, 32'h0000_0001, OKAY);
        `CHECK(mon_irq == 1'b1, ("EXPIRED cleared by a write of 0 or without wstrb[0]"))
        wr(8'h0C, 32'h0000_0001, 4'h1, OKAY);
        `CHECK(mon_irq == 1'b0, ("irq still high after STATUS clear"))
        rdchk(8'h0C, 32'h0, OKAY);
        oneshot_timed(32'd1, 1);
        oneshot_timed(32'd0, 1);
        oneshot_timed(32'd3, 3);

        // ---------------- T7: IE on a pending expiry ----------------
        wr(8'h04, 32'd3, 4'hF, OKAY);
        rc = rise_cnt;
        wr(8'h00, 32'h0000_0001, 4'h1, OKAY);
        wait_cycles(10);
        `CHECK(mon_irq == 1'b0, ("irq high with IE 0"))
        rdchk(8'h0C, 32'h0000_0001, OKAY);
        rdchk(8'h00, 32'h0, OKAY);
        wr(8'h00, 32'h0000_0002, 4'h1, OKAY);
        E = last_eff;
        `CHECK(mon_irq == 1'b1, ("irq did not rise when IE written 1 on a pending expiry"))
        `CHECK(rise_cnt == rc + 1 && last_rise == E, ("irq rose on edge %0d, expected %0d", last_rise, E))
        wr(8'h00, 32'h0000_0000, 4'h1, OKAY);
        `CHECK(mon_irq == 1'b0, ("irq still high after IE written 0"))
        rdchk(8'h0C, 32'h0000_0001, OKAY);
        wr(8'h0C, 32'h0000_0001, 4'h1, OKAY);
        rdchk(8'h0C, 32'h0, OKAY);

        // ---------------- T8: periodic timed over several periods ----------------
        wr(8'h04, 32'd5, 4'hF, OKAY);
        rc = rise_cnt;
        wr(8'h00, 32'h0000_0007, 4'h1, OKAY);
        E = last_eff;
        wait_irq(50);
        `CHECK(last_rise == E + 5, ("periodic: 1st expiry on edge %0d, expected %0d", last_rise, E + 5))
        write_at(E + 7, 8'h0C, 32'h0000_0001, 4'h1);
        `CHECK(mon_irq == 1'b0, ("periodic: irq high after clear"))
        wait_irq(50);
        `CHECK(last_rise == E + 10, ("periodic: 2nd expiry on edge %0d, expected %0d", last_rise, E + 10))
        write_at(E + 12, 8'h0C, 32'h0000_0001, 4'h1);
        `CHECK(mon_irq == 1'b0, ("periodic: irq high after clear"))
        write_at(E + 15, 8'h0C, 32'h0000_0001, 4'h1);
        `CHECK(mon_irq == 1'b1, ("periodic: clear on the count-end edge lost the expiry"))
        `CHECK(last_rise == E + 15, ("periodic: 3rd expiry on edge %0d, expected %0d", last_rise, E + 15))
        rdchk(8'h0C, 32'h0000_0001, OKAY);
        write_at(E + 22, 8'h0C, 32'h0000_0001, 4'h1);
        `CHECK(mon_irq == 1'b0, ("periodic: irq high after clear"))
        `CHECK(rise_cnt == rc + 3, ("periodic: %0d rises, expected 3", rise_cnt - rc))
        axi_read(8'h08, 0, rdat, r, acc);
        expv = 5 - ((acc - 1 - E) % 5);
        `CHECK(rdat == expv && r == OKAY, ("periodic COUNT 0x%h, expected %0d", rdat, expv))
        wait_irq(50);
        `CHECK(last_rise == E + 25, ("periodic: 5th expiry on edge %0d, expected %0d", last_rise, E + 25))
        `CHECK(rise_cnt == rc + 4, ("periodic: %0d rises, expected 4", rise_cnt - rc))
        rdchk(8'h00, 32'h0000_0007, OKAY);
        // stop the periodic timer
        wr(8'h00, 32'h0000_0006, 4'h1, OKAY);
        S = last_eff;
        expv = 5 - ((S - E) % 5);
        wr(8'h0C, 32'h0000_0001, 4'h1, OKAY);
        rc2 = rise_cnt;
        axi_read(8'h08, 0, rdat, r, acc);
        `CHECK(rdat == expv, ("periodic stop: COUNT 0x%h, expected %0d", rdat, expv))
        wait_cycles(20);
        axi_read(8'h08, 0, rdat2, r, acc);
        `CHECK(rdat2 == rdat, ("periodic stop: COUNT moved from 0x%h to 0x%h", rdat, rdat2))
        `CHECK(rise_cnt == rc2 && mon_irq == 1'b0, ("periodic stop: expiry after stop"))
        rdchk(8'h00, 32'h0000_0006, OKAY);

        // ---------------- T9: stop freezes COUNT (one-shot) ----------------
        wr(8'h04, 32'd100, 4'hF, OKAY);
        rc = rise_cnt;
        wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
        E = last_eff;
        write_at(E + 20, 8'h00, 32'h0000_0002, 4'h1);
        rdchk(8'h08, 32'd80, OKAY);
        wait_cycles(30);
        rdchk(8'h08, 32'd80, OKAY);
        rdchk(8'h00, 32'h0000_0002, OKAY);
        wait_cycles(100);
        `CHECK(rise_cnt == rc && mon_irq == 1'b0, ("stopped count still expired"))
        rdchk(8'h0C, 32'h0, OKAY);
        rdchk(8'h08, 32'd80, OKAY);

        // ---------------- T10: restart while counting ----------------
        wr(8'h04, 32'd10, 4'hF, OKAY);
        rc = rise_cnt;
        wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
        E = last_eff;
        write_at(E + 6, 8'h00, 32'h0000_0003, 4'h1);
        S = E + 6;
        axi_read(8'h08, 0, rdat, r, acc);
        expv = 10 - (acc - 1 - S);
        `CHECK(rdat == expv, ("restart: COUNT 0x%h, expected %0d", rdat, expv))
        wait_irq(50);
        `CHECK(last_rise == S + 10, ("restart: expiry on edge %0d, expected %0d", last_rise, S + 10))
        `CHECK(rise_cnt == rc + 1, ("restart: %0d rises, expected 1", rise_cnt - rc))
        rdchk(8'h00, 32'h0000_0002, OKAY);
        wr(8'h0C, 32'h0000_0001, 4'h1, OKAY);

        // ---------------- T11: restart on the count-end edge ----------------
        wr(8'h04, 32'd4, 4'hF, OKAY);
        rc = rise_cnt;
        wr(8'h00, 32'h0000_0003, 4'h1, OKAY);
        E = last_eff;
        write_at(E + 4, 8'h00, 32'h0000_0003, 4'h1);
        `CHECK(last_rise == E + 4 && rise_cnt == rc + 1, ("restart on end: expiry on edge %0d, expected %0d", last_rise, E + 4))
        `CHECK(mon_irq == 1'b1, ("restart on end: EXPIRED not set"))
        write_at(E + 6, 8'h0C, 32'h0000_0001, 4'h1);
        `CHECK(mon_irq == 1'b0, ("restart on end: irq high after clear"))
        wait_irq(20);
        `CHECK(last_rise == E + 8, ("restart on end: 2nd expiry on edge %0d, expected %0d", last_rise, E + 8))
        `CHECK(rise_cnt == rc + 2, ("restart on end: %0d rises, expected 2", rise_cnt - rc))
        rdchk(8'h00, 32'h0000_0002, OKAY);
        rdchk(8'h08, 32'h0, OKAY);
        wr(8'h0C, 32'h0000_0001, 4'h1, OKAY);

        // ---------------- T12: stop on the count-end edge (periodic) ----------------
        wr(8'h04, 32'd4, 4'hF, OKAY);
        rc = rise_cnt;
        wr(8'h00, 32'h0000_0007, 4'h1, OKAY);
        E = last_eff;
        write_at(E + 4, 8'h00, 32'h0000_0006, 4'h1);
        `CHECK(last_rise == E + 4 && rise_cnt == rc + 1, ("stop on end: expiry on edge %0d, expected %0d", last_rise, E + 4))
        rdchk(8'h08, 32'd4, OKAY);
        rdchk(8'h00, 32'h0000_0006, OKAY);
        wr(8'h0C, 32'h0000_0001, 4'h1, OKAY);
        wait_cycles(20);
        `CHECK(rise_cnt == rc + 1 && mon_irq == 1'b0, ("stop on end: expiry after stop"))
        rdchk(8'h08, 32'd4, OKAY);
        rdchk(8'h0C, 32'h0, OKAY);
        wr(8'h00, 32'h0000_0000, 4'h1, OKAY);

        // ---------------- T13: reset during a count and a pending response ----------------
        wr(8'h04, 32'd50, 4'hF, OKAY);
        wr(8'h00, 32'h0000_0007, 4'h1, OKAY);
        wait_cycles(10);
        tb_awaddr  = 8'h04;
        tb_wdata   = 32'h0000_0099;
        tb_wstrb   = 4'hF;
        tb_awvalid = 1'b1;
        tb_wvalid  = 1'b1;
        tick;
        tb_awvalid = 1'b0;
        tb_wvalid  = 1'b0;
        `CHECK(bvalid == 1'b1, ("reset test: BVALID not pending before reset"))
        aresetn = 1'b0;
        tick;
        tick;
        `CHECK(bvalid == 1'b0 && rvalid == 1'b0 && mon_irq == 1'b0, ("reset did not drop BVALID/RVALID/irq"))
        `CHECK(awready == 1'b1 && wready == 1'b1 && arready == 1'b1, ("READYs not high after reset"))
        aresetn = 1'b1;
        rdchk(8'h00, 32'h0, OKAY);
        rdchk(8'h04, 32'h0, OKAY);
        rdchk(8'h08, 32'h0, OKAY);
        rdchk(8'h0C, 32'h0, OKAY);
        wait_cycles(80);
        `CHECK(rise_cnt == 0 && mon_irq == 1'b0, ("expiry after reset during a count"))
        rdchk(8'h08, 32'h0, OKAY);
        rdchk(8'h0C, 32'h0, OKAY);

        // ---------------- T14: ADDR_WIDTH 8 lane ----------------
        sel8 = 1'b1;
        @(negedge clk);
        rdchk(8'h00, 32'h0, OKAY);
        rdchk(8'h04, 32'h0, OKAY);
        rdchk(8'h08, 32'h0, OKAY);
        rdchk(8'h0C, 32'h0, OKAY);
        wr(8'h04, 32'h0000_0006, 4'hF, OKAY);
        mload = 32'h0000_0006;
        rdchk(8'h04, mload, OKAY);
        rdchk(8'h10, 32'h0, SLVERR);
        rdchk(8'h14, 32'h0, SLVERR);
        rdchk(8'h18, 32'h0, SLVERR);
        rdchk(8'h1C, 32'h0, SLVERR);
        rdchk(8'h40, 32'h0, SLVERR);
        rdchk(8'h84, 32'h0, SLVERR);
        rdchk(8'hF4, 32'h0, SLVERR);
        rdchk(8'hFC, 32'h0, SLVERR);
        rdchk(8'h15, 32'h0, SLVERR);
        wr(8'h14, 32'hCAFE_F00D, 4'hF, SLVERR);
        rdchk(8'h04, mload, OKAY);
        wr(8'h10, 32'h0000_0007, 4'h1, SLVERR);
        rdchk(8'h00, 32'h0, OKAY);
        wait_cycles(10);
        rdchk(8'h08, 32'h0, OKAY);
        `CHECK(mon_irq == 1'b0, ("aw8: write to 0x10 aliased CTRL"))
        wr(8'h18, 32'h0000_0001, 4'hF, SLVERR);
        wr(8'h1C, 32'h0000_0001, 4'h1, SLVERR);
        wr(8'h94, 32'h1234_5678, 4'hF, SLVERR);
        wr(8'h08, 32'h0000_0001, 4'hF, SLVERR);
        rdchk(8'h04, mload, OKAY);
        rdchk(8'h08, 32'h0, OKAY);
        wr(8'h04, 32'h1200_0000, 4'b1000, OKAY);
        mload = merge(mload, 32'h1200_0000, 4'b1000);
        rdchk(8'h04, mload, OKAY);
        oneshot_timed(32'd7, 7);
        rdchk(8'h0C, 32'h0, OKAY);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

